// Deterministic browser-side sanity tests for the Phase 1 global keyframe
// camera path (cameraPathSchema.ts, cameraPath.ts). Two fixtures are consumed,
// both generated by the REAL Python builder (camera_path.py) with REAL
// cv2.estimateAffinePartial2D RANSAC — not hand-authored JSON — so a schema or
// direction bug in either language would show up here:
//   - /tmp/ava-camera-path-fixture.json        a stable, never-lost path
//   - /tmp/ava-camera-path-relock-fixture.json a genuine loss + successful relock
// Regenerate both with: .venv/bin/python <ad-hoc script — see camera-path
// worker sanity for the exact construction> if they are missing; this script
// falls back to skipping fixture-dependent checks (not failing) so it stays
// runnable in an environment without the Python venv, while everything that
// only needs the TS module itself still runs and fails loudly on a real bug.
import assert from "node:assert/strict";
import { execFileSync } from "node:child_process";
import { existsSync, mkdirSync, readFileSync, rmSync } from "node:fs";
import { createRequire } from "node:module";
import path from "node:path";

const root = process.cwd();
const out = path.join(root, ".camera-path-sanity-tmp");
const require = createRequire(import.meta.url);
let ok = true;
const check = (label, condition) => {
  console.log(`${condition ? "PASS" : "FAIL"}  ${label}`);
  if (!condition) ok = false;
};

rmSync(out, { recursive: true, force: true });
mkdirSync(out, { recursive: true });
try {
  execFileSync("npx", [
    "tsc",
    "src/lib/video/cameraPath.ts", "src/lib/video/cameraPathSchema.ts",
    "src/lib/calibration/zoneAnchors.ts", "src/lib/video/recordingMode.ts",
    "--outDir", out, "--rootDir", "src/lib", "--module", "commonjs", "--target", "es2022",
    "--skipLibCheck", "--esModuleInterop", "--strict",
  ], { cwd: root, stdio: "inherit" });
  const cameraPath = require(path.join(out, "video/cameraPath.js"));
  const cameraPathSchema = require(path.join(out, "video/cameraPathSchema.js"));

  // --- 12. schema shape / result-contract parsing ---
  check("12. cameraPath is optional (absent -> valid undefined, legacy analyses unaffected)",
    cameraPathSchema.cameraPathArtifactSchema.optional().safeParse(undefined).success);

  const stableFixturePath = "/tmp/ava-camera-path-fixture.json";
  const relockFixturePath = "/tmp/ava-camera-path-relock-fixture.json";
  const haveFixtures = existsSync(stableFixturePath) && existsSync(relockFixturePath);
  if (!haveFixtures) {
    console.log("SKIP  fixture-dependent checks (regenerate the two /tmp fixtures with the Python venv first)");
  } else {
    const stable = JSON.parse(readFileSync(stableFixturePath, "utf8"));
    const relock = JSON.parse(readFileSync(relockFixturePath, "utf8"));

    const stableParsed = cameraPathSchema.cameraPathArtifactSchema.safeParse(stable);
    check("12. the REAL Python-built stable-path artifact validates against the TS Zod schema",
      stableParsed.success);
    const relockParsed = cameraPathSchema.cameraPathArtifactSchema.safeParse(relock);
    check("12. the REAL Python-built loss+relock artifact validates against the TS Zod schema",
      relockParsed.success);

    if (stableParsed.success) {
      const WIDTH = stable.sourceWidth, HEIGHT = stable.sourceHeight;
      const index = cameraPath.indexCameraFramePaths(stableParsed.data);
      check("1. stable path: every frame is globally available",
        Array.from(index.values()).every((entry) =>
          cameraPath.lookupCameraFramePath(index, entry.frameIndex).globallyAvailable));

      // --- 11. frame->global / global->frame round trip on REAL resolved matrices ---
      const sample = index.get(50);
      const g = cameraPath.globalPointToFrame(index, 50, { x: 0.4, y: 0.6 }, WIDTH, HEIGHT);
      const back = cameraPath.framePointToGlobal(index, 50, g.point, WIDTH, HEIGHT);
      check("11. globalPointToFrame -> framePointToGlobal round-trips to within 1e-6",
        g.available && back.available
        && Math.abs(back.point.x - 0.4) < 1e-6 && Math.abs(back.point.y - 0.6) < 1e-6);
      check("11. a sampled anchored frame actually carries both resolved matrices",
        sample.frameToGlobalMatrix != null && sample.globalToFrameMatrix != null);
    }

    if (relockParsed.success) {
      const data = relockParsed.data;
      const WIDTH = data.sourceWidth, HEIGHT = data.sourceHeight;
      const index = cameraPath.indexCameraFramePaths(data);
      const lossStart = 40, lossEnd = 139, relockFrame = 141;

      // --- 7. world overlays disappear during the unavailable interval ---
      check("7. deep in the real loss interval, the frame is NOT globally available",
        !cameraPath.lookupCameraFramePath(index, lossStart + 5).globallyAvailable);

      // --- 8. world overlays resume after a successful relock ---
      check("8. shortly after the real relock frame, the frame IS globally available again",
        cameraPath.lookupCameraFramePath(index, relockFrame + 2).globallyAvailable);
      check("8. the artifact's own diagnostics confirm at least one real relock succeeded",
        data.diagnostics.relockSuccessCount >= 1);

      // A world point stored (created) BEFORE the loss, at a frame that IS
      // globally available, must still be correctly reprojectable into a
      // frame AFTER the relock — proving contacts/gates created pre-gap
      // survive a relock rather than needing to be recreated (Part 9).
      const createdEarly = cameraPath.framePointToGlobal(index, 10, { x: 0.5, y: 0.5 }, WIDTH, HEIGHT);
      const projectedAfterRelock = cameraPath.globalPointToFrame(
        index, relockFrame + 5, createdEarly.point, WIDTH, HEIGHT,
      );
      check("8. a pre-loss contact/gate anchor is still globally projectable after the relock",
        createdEarly.available && projectedAfterRelock.available);

      // --- 9. identical coordinates before/after random-access scrubbing ---
      const targetFrame = relockFrame + 5;
      const globalPoint = { x: 0.33, y: 0.61 };
      const direct = cameraPath.globalPointToFrame(index, targetFrame, globalPoint, WIDTH, HEIGHT);
      // "Visit" many unrelated frames first (forward, backward, out of order) —
      // a chain-walking implementation would risk carrying state between
      // calls; a direct-lookup one cannot.
      for (const f of [5, 155, 12, relockFrame, 0, 90, lossStart + 2]) {
        cameraPath.globalPointToFrame(index, f, globalPoint, WIDTH, HEIGHT);
      }
      const afterScrubbing = cameraPath.globalPointToFrame(index, targetFrame, globalPoint, WIDTH, HEIGHT);
      check("9. identical projection before and after visiting unrelated frames in random order",
        JSON.stringify(direct) === JSON.stringify(afterScrubbing));

      // --- 14. gates and contacts read the SAME artifact/frame transform ---
      const gateIndex = cameraPath.indexCameraFramePaths(data);
      const contactIndex = cameraPath.indexCameraFramePaths(data);
      const gateLookup = cameraPath.lookupCameraFramePath(gateIndex, targetFrame);
      const contactLookup = cameraPath.lookupCameraFramePath(contactIndex, targetFrame);
      check("14. gate and contact consumption resolve to byte-identical frame transforms",
        JSON.stringify(gateLookup.framePath) === JSON.stringify(contactLookup.framePath));
      check("14. both consumption paths agree on the artifact version",
        data.version === cameraPathSchema.CAMERA_PATH_VERSION);

      // --- 15. no browser-side sequential accumulation ---
      // Project frame 155 directly (cold) vs. after "walking" every frame from
      // 0 to 154 first (warm) — a chain-walking implementation could differ
      // (accumulated float drift, or worse, actually depend on having visited
      // every frame); a direct-lookup implementation cannot.
      const cold = cameraPath.globalPointToFrame(index, 155, globalPoint, WIDTH, HEIGHT);
      for (let f = 0; f < 155; f += 1) cameraPath.globalPointToFrame(index, f, globalPoint, WIDTH, HEIGHT);
      const warm = cameraPath.globalPointToFrame(index, 155, globalPoint, WIDTH, HEIGHT);
      check("15. projecting frame 155 cold vs. after visiting every prior frame is byte-identical",
        JSON.stringify(cold) === JSON.stringify(warm));
      check("15. globalPointToFrame's signature is exactly (index, frameIndex, point, width, height) — no accumulator/previous-frame parameter",
        cameraPath.globalPointToFrame.length === 5);
    }
  }
} finally {
  rmSync(out, { recursive: true, force: true });
}

console.log(ok ? "\nALL PASSED" : "\nFAILURES PRESENT");
process.exit(ok ? 0 : 1);
